expression:
local({
  code <- stats::ave(as.numeric(ethnicity_code), pid, FUN = function(x) if (all(is.na(x))) x else x[!is.na(x)][1])
  case_when(is.na(code) ~ "Unknown", code == 1 ~ "Non-minority", .default = "Minority")
})

recode_values(
  stats::ave(household_income_pc, wave, FUN = function(x) {
    findInterval(x, stats::quantile(x, c(1 / 3, 2 / 3), na.rm = TRUE)) + 1
  }),
  1 ~ "Low",
  2 ~ "Medium",
  3 ~ "High",
  default = "Unknown"
)
